class Solution {
private:
    unordered_map<string, string> longToShort;
    unordered_map<string, string> shortToLong;
    string chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    int len = 6;

    string getRandomString() {
        string s = "";
        for (int i = 0; i < len; i++) {
            s += chars[rand() % chars.size()];
        }
        return s;
    }

public:
    // Encodes a URL to a shortened URL.
    string encode(string longUrl) {
        if (longToShort.count(longUrl)) {
            return "http://tinyurl.com/" + longToShort[longUrl];
        }
        string key = getRandomString();
        while (shortToLong.count(key)) {
            key = getRandomString();
        }
        longToShort[longUrl] = key;
        shortToLong[key] = longUrl;
        return "http://tinyurl.com/" + key;
    }

    // Decodes a shortened URL to its original URL.
    string decode(string shortUrl) {
        string key = shortUrl.substr(shortUrl.length() - len);
        return shortToLong[key];
    }
};
